with cleaned as (select *, coalesce(dept_name, 'Unknown') as dept_name_filled from departments where dept_name is not null and dept_name = 'HR') select location, dept_name, size(collect_set(location)) as num_locations, sort_array(collect_set(dept_name)) as dept_name_list, max(budget) filter (where dept_name = 'HR') as hr_max_budget, count(case when location = 'Berlin' then 1 end) as berlin_count, approx_percentile(budget, array(0.25, 0.5, 0.75)) as budget_quartiles from cleaned group by 1, 2 having num_locations > 1
